def subtract(a, b):
    def normalize(intervals):
        # Filter out empty intervals and sort
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []

        valid.sort()

        # Merge overlapping and touching intervals
        merged = []
        for start, end in valid:
            if merged and start <= merged[-1][1]:
                # Overlapping or touching - merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Non-overlapping - add new interval
                merged.append([start, end])

        return merged

    # Normalize both a and b
    a_norm = normalize(a)
    b_norm = normalize(b)

    if not a_norm:
        return []
    if not b_norm:
        return a_norm

    # For each interval in a, subtract all intervals in b
    result = []

    for a_start, a_end in a_norm:
        # Keep track of the current segment of a that hasn't been subtracted
        current_segments = [[a_start, a_end]]

        # Subtract each interval in b
        for b_start, b_end in b_norm:
            new_segments = []

            for seg_start, seg_end in current_segments:
                # If b doesn't overlap with this segment, keep the whole segment
                if b_end <= seg_start or b_start >= seg_end:
                    new_segments.append([seg_start, seg_end])
                else:
                    # b overlaps with this segment
                    # Keep the part before b
                    if seg_start < b_start:
                        new_segments.append([seg_start, b_start])
                    # Keep the part after b
                    if b_end < seg_end:
                        new_segments.append([b_end, seg_end])

            current_segments = new_segments

        result.extend(current_segments)

    # Sort result (should already be sorted but ensure it)
    result.sort()

    return result

